+package hotel.documents;
+
+import hotel.reservations.CorporateGuest;
+import hotel.reservations.PriceCalculator;
+import hotel.reservations.Reservation;
+import hotel.rooms.Room;
+import hotel.rooms.RoomType;
+import java.math.BigDecimal;
+import java.time.LocalDate;
+
+/** The invoice a company gets (CNPJ identification, with ISS tax withheld). */
+public record CorporateInvoice(
+        long reservationId,
+        String companyName,
+        String companyCnpj,
+        String guestName,
+        int roomNumber,
+        RoomType roomType,
+        LocalDate checkIn,
+        LocalDate checkOut,
+        int nights,
+        BigDecimal subtotal,
+        BigDecimal discount,
+        BigDecimal total,
+        BigDecimal issWithheld) implements ReservationDocument {
+
+    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
+
+    public CorporateInvoice(Reservation reservation, Room room, CorporateGuest guest) {
+        this(
+                reservation.id(),
+                guest.companyName(),
+                guest.cnpj(),
+                guest.name(),
+                room.number(),
+                room.type(),
+                reservation.checkIn(),
+                reservation.checkOut(),
