145	    private static Reservation read(ResultSet row) throws SQLException {
146	        String name = row.getString("guest_name");
147	        String email = row.getString("guest_email");
148	        String cpf = row.getString("guest_cpf");
149	        String cnpj = row.getString("company_cnpj");
150	        String companyName = row.getString("company_name");
151	        String passport = row.getString("guest_passport");
152	        String country = row.getString("guest_country");
153	
154	        Guest guest;
155	        if (cpf != null) {
156	            guest = new IndividualGuest(name, email, cpf);
157	        } else if (cnpj != null) {
158	            guest = new CorporateGuest(name, email, cnpj, companyName);
159	        } else {
160	            guest = new ForeignGuest(name, email, passport, country);
161	        }
162	
163	        NewReservation request = new NewReservation(
164	                row.getInt("room_number"),
165	                guest,
166	                row.getDate("check_in").toLocalDate(),
167	                row.getDate("check_out").toLocalDate(),
168	                row.getInt("guests"),
169	                RatePlan.valueOf(row.getString("rate_plan")));
170	        Price price = new Price(
171	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
172	                row.getBigDecimal("total"));
173	        return new Reservation(
174	                row.getLong("id"),
175	                request,
176	                price,
177	                ReservationStatus.valueOf(row.getString("status")),
178	                row.getBigDecimal("amount_paid"),
179	                row.getBigDecimal("refund"));
180	    }
